      "document-gallery-id": 12,
      "target": {
        "type": "gallery",
        "id": 12
      },
      "original-src": "https://storage.example.com/developer/images/17/original/test-image.png",
      "slim-src": "https://storage.example.com/developer/images/17/slim/test-image.png",
